-- +goose Up
-- RTG-07 (docs/decisions.md Q-42): a dedicated "processor" axis of ropa.template_sets' own schema —
-- distinct from RTG-01's own 3 processor-role examples embedded in its standard job-category set
-- (set_type='standard') — this is the real set_type='processor' value the baseline migration's own
-- CHECK constraint already reserved (ERD-09), unused until now. This migration only seeds data, no
-- schema change. Content is a DRAFT written for this pass (no official "ประกาศ RoPA ผู้ประมวลผล พ.ศ.
-- 2565" template document was available here), covering the fields a processor's own RoPA record
-- needs under ม.40(3) in the exact ropa.activity_templates.defaults/rationale shape RTG-01/02/03
-- already use, keyed by code against the real org.lawful_bases/data_categories/data_subject_types
-- and ropa security_controls codes already seeded (00031/00040) — the same "seed a draft + flag for
-- legal review" move ORG-07 (Q-20), ROPA-09 (Q-25), PNG-03 (Q-14), DPIA-01 (Q-26), RTG-01 (Q-28),
-- PNG-11 (Q-38), RTG-02 (Q-39) and RTG-03 (Q-40) already made. lawful_basis_code is CONTRACT
-- throughout — the processor's own purpose is always performing the service contract with the
-- controller, never the controller's own basis for the underlying processing (ROPA-04's own export
-- already excludes lawful_basis_code from the processor-RoPA CSV for exactly this reason — it stays
-- on the template/activity record itself only because ropa.activity_purposes requires one). Global
-- rows (tenant_id NULL) need RLS force lifted inside this migration, as in 00019/00031/00040/00049/
-- 00082/00084 (restored before commit).

ALTER TABLE ropa.template_sets NO FORCE ROW LEVEL SECURITY;
ALTER TABLE ropa.activity_templates NO FORCE ROW LEVEL SECURITY;

INSERT INTO ropa.template_sets (id, name, set_type, industry, status, published_at) VALUES
    ('00000000-0000-7000-8000-000000000018', 'ชุดกิจกรรมสำหรับผู้ประมวลผลข้อมูล ตามประกาศ RoPA ผู้ประมวลผล พ.ศ. 2565', 'processor', NULL, 'published', now());

INSERT INTO ropa.activity_templates (template_set_id, code, name_th, name_en, job_category, role, defaults, rationale, legal_refs) VALUES
    ('00000000-0000-7000-8000-000000000018', 'proc_payroll_outsourcing', 'ประมวลผลข้อมูลเงินเดือนตามสัญญาให้บริการ', 'Payroll processing under a service contract', 'payroll', 'processor', '{"description_th": "ประมวลผลข้อมูลเงินเดือนและสวัสดิการของพนักงานผู้ว่าจ้างตามคำสั่งและสัญญาประมวลผลข้อมูล (DPA)", "description_en": "Process the controller''s own employee payroll and benefits data under its instructions and data processing agreement (DPA)", "purposes": [{"purpose_text_th": "ให้บริการประมวลผลเงินเดือนตามสัญญาประมวลผลข้อมูลกับผู้ว่าจ้าง", "purpose_text_en": "Provide payroll processing services under the data processing agreement with the controller", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "employee", "source": "indirect"}, {"data_category_code": "financial", "subject_type_code": "employee", "source": "indirect"}], "recipients": [{"recipient_role": "controller", "note_th": "ผู้ว่าจ้าง (ผู้ควบคุมข้อมูล) ผู้ให้คำสั่งประมวลผล"}], "retention": [{"retention_months": 12, "retention_basis_th": "เก็บตามระยะเวลาที่กำหนดในสัญญาประมวลผลข้อมูล นับจากวันที่สิ้นสุดบริการในรอบนั้น", "trigger_event_th": "สิ้นสุดรอบบริการตามสัญญา หรือสัญญาสิ้นสุด", "disposal_method": "return"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายของผู้ประมวลผลคือการปฏิบัติตามสัญญาประมวลผลข้อมูลกับผู้ว่าจ้าง ไม่ใช่ฐานของผู้ควบคุมข้อมูลสำหรับกิจกรรม \"ประมวลผลข้อมูลเงินเดือนตามสัญญาให้บริการ\"", "retention_th": "ระยะเวลาเก็บรักษาต้องสอดคล้องกับข้อกำหนดในสัญญาประมวลผลข้อมูล โปรดปรับตามสัญญาจริงของแต่ละราย", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างตามประกาศ RoPA ผู้ประมวลผล พ.ศ. 2565 ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง และระบุ controller_party_id ของผู้ว่าจ้างแต่ละรายเอง"}'::jsonb, ARRAY['ม.40(3)']),
    ('00000000-0000-7000-8000-000000000018', 'proc_customer_support_outsourcing', 'ให้บริการศูนย์ดูแลลูกค้าตามสัญญาให้บริการ', 'Outsourced customer support services', 'customer_service', 'processor', '{"description_th": "รับและตอบข้อซักถามของลูกค้าของผู้ว่าจ้างผ่านศูนย์บริการตามคำสั่งและสัญญาประมวลผลข้อมูล", "description_en": "Receive and respond to the controller''s own customers'' inquiries through a support center under its instructions and DPA", "purposes": [{"purpose_text_th": "ให้บริการศูนย์ดูแลลูกค้าตามสัญญาประมวลผลข้อมูลกับผู้ว่าจ้าง", "purpose_text_en": "Provide customer support services under the data processing agreement with the controller", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "indirect"}, {"data_category_code": "contact", "subject_type_code": "customer", "source": "indirect"}], "recipients": [{"recipient_role": "controller", "note_th": "ผู้ว่าจ้าง (ผู้ควบคุมข้อมูล) ผู้ให้คำสั่งประมวลผล"}], "retention": [{"retention_months": 6, "retention_basis_th": "เก็บตามระยะเวลาที่กำหนดในสัญญาประมวลผลข้อมูล นับจากวันที่ปิดเรื่อง", "trigger_event_th": "ปิดเรื่องร้องขอ หรือสัญญาสิ้นสุด", "disposal_method": "delete"}], "security_controls": ["AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายของผู้ประมวลผลคือการปฏิบัติตามสัญญาประมวลผลข้อมูลกับผู้ว่าจ้าง ไม่ใช่ฐานของผู้ควบคุมข้อมูลสำหรับกิจกรรม \"ให้บริการศูนย์ดูแลลูกค้าตามสัญญาให้บริการ\"", "retention_th": "ระยะเวลาเก็บรักษาต้องสอดคล้องกับข้อกำหนดในสัญญาประมวลผลข้อมูล โปรดปรับตามสัญญาจริงของแต่ละราย", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างตามประกาศ RoPA ผู้ประมวลผล พ.ศ. 2565 ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง และระบุ controller_party_id ของผู้ว่าจ้างแต่ละรายเอง"}'::jsonb, ARRAY['ม.40(3)']),
    ('00000000-0000-7000-8000-000000000018', 'proc_cloud_hosting', 'ให้บริการโฮสต์ข้อมูลบนคลาวด์ตามสัญญาให้บริการ', 'Cloud hosting services under a service contract', 'it_support', 'processor', '{"description_th": "จัดเก็บและสำรองข้อมูลของผู้ว่าจ้างบนระบบคลาวด์ตามคำสั่งและสัญญาประมวลผลข้อมูล", "description_en": "Store and back up the controller''s own data on cloud infrastructure under its instructions and DPA", "purposes": [{"purpose_text_th": "ให้บริการจัดเก็บและสำรองข้อมูลตามสัญญาประมวลผลข้อมูลกับผู้ว่าจ้าง", "purpose_text_en": "Provide data storage and backup services under the data processing agreement with the controller", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "indirect"}], "recipients": [{"recipient_role": "controller", "note_th": "ผู้ว่าจ้าง (ผู้ควบคุมข้อมูล) ผู้ให้คำสั่งประมวลผล"}], "retention": [{"retention_months": 1, "retention_basis_th": "เก็บเฉพาะระหว่างระยะเวลาของสัญญาให้บริการโฮสติ้ง คืนหรือทำลายข้อมูลทันทีที่สัญญาสิ้นสุด", "trigger_event_th": "สัญญาให้บริการสิ้นสุด", "disposal_method": "return"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายของผู้ประมวลผลคือการปฏิบัติตามสัญญาประมวลผลข้อมูลกับผู้ว่าจ้าง ไม่ใช่ฐานของผู้ควบคุมข้อมูลสำหรับกิจกรรม \"ให้บริการโฮสต์ข้อมูลบนคลาวด์ตามสัญญาให้บริการ\"", "retention_th": "ระยะเวลาเก็บรักษาต้องสอดคล้องกับข้อกำหนดในสัญญาประมวลผลข้อมูล โปรดปรับตามสัญญาจริงของแต่ละราย", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างตามประกาศ RoPA ผู้ประมวลผล พ.ศ. 2565 ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง และระบุ controller_party_id ของผู้ว่าจ้างแต่ละรายเอง"}'::jsonb, ARRAY['ม.40(3)']);

